function minStride(labels) {
    if (labels.length < 2) { return 0; }
    const ordered = labels.slice().sort(function (p, q) { return p - q; });
    let best = 0;
    for (let idx = 1; idx < ordered.length; idx++) {
        const gap = ordered[idx] - ordered[idx - 1];
        if (gap > best) { best = gap; }
    }
    return best;
}

